package org.springframework.samples.petclinic.rest.advice;

import java.util.Locale;
import java.util.Set;

import org.springframework.core.MethodParameter;
import org.springframework.http.MediaType;
import org.springframework.http.converter.HttpMessageConverter;
import org.springframework.http.server.ServerHttpRequest;
import org.springframework.http.server.ServerHttpResponse;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.servlet.mvc.method.annotation.ResponseBodyAdvice;

/**
 * Flags every owner response with {@code riskFlag}: true when any risk signal holds — the owner is a
 * possible duplicate, the email domain is disposable-adjacent (a subdomain of a known disposable
 * domain), or the owner's city is at or over its soft capacity of {@value #SOFT_CAPACITY} owners
 * (compared case-insensitively with surrounding whitespace trimmed); otherwise false. Purely
 * informational, so it never rejects a request.
 */
@ControllerAdvice
public class OwnerRiskFlagAdvice implements ResponseBodyAdvice<Object> {

    private static final int SOFT_CAPACITY = 40;

    private static final Set<String> DISPOSABLE_DOMAINS =
        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    private final ClinicService clinicService;

    public OwnerRiskFlagAdvice(ClinicService clinicService) {
        this.clinicService = clinicService;
    }

    @Override
    public boolean supports(MethodParameter returnType,
                            Class<? extends HttpMessageConverter<?>> converterType) {
        return true;
    }

    @Override
    public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType,
                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,
                                  ServerHttpRequest request, ServerHttpResponse response) {
        if (body instanceof OwnerDto owner) {
            owner.setRiskFlag(Boolean.TRUE.equals(owner.getPossibleDuplicate())
                || disposableAdjacent(owner.getEmail())
                || cityCount(normalize(owner.getCity())) >= SOFT_CAPACITY);
        }
        return body;
    }

    private boolean disposableAdjacent(String email) {
        if (email == null) {
            return false;
        }
        String domain = normalize(email.substring(email.lastIndexOf('@') + 1));
        for (String disposable : DISPOSABLE_DOMAINS) {
            if (domain.endsWith("." + disposable)) {
                return true;
            }
        }
        return false;
    }

    private int cityCount(String city) {
        if (city.isEmpty()) {
            return 0;
        }
        int count = 0;
        for (Owner existing : clinicService.findAllOwners()) {
            if (city.equals(normalize(existing.getCity()))) {
                count++;
            }
        }
        return count;
    }

    private String normalize(String value) {
        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
    }
}

